window.MG_LAZY_DATA["data/lazy/resources/comm-v28-076-d6ddcba2ca56d225.json"]={sha256:"d6ddcba2ca56d22544c9afb87447c6fce594970a3e0c1164a4278ff8eecac518",value:{"sources":[{"id":"v28-case-12394b4a22706b67","url":"https://ocw.mit.edu/courses/6-450-principles-of-digital-communications-i-fall-2006/","title":"Principles of Digital Communications I","titleEn":"Principles of Digital Communications I","publisher":"MIT OpenCourseWare","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"comm-v28-076","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"comm-v28-076","related":[{"id":"comm-v28-077","referenceUrls":["https://ocw.mit.edu/courses/6-450-principles-of-digital-communications-i-fall-2006/"],"title":"同步檢波 AM：載波功率與邊帶效率","titleEn":"Coherent AM reception: carrier power and sideband efficiency","why":"用兩課的可觀察驗收條件比較模型邊界：交付物能重現 144000 Hz 與 84000 Hz，保留失敗情境且每個通過判定有明確門檻；需分開列出模型未涵蓋的實際系統驗證。","whyEn":"Compare model boundaries using observable acceptance criteria: The artifacts must reproduce 144000 Hz and 84000 Hz, preserve failing scenarios and attach a threshold to each pass decision; list actual-system validation outside this model separately.","difference":"能推導並解釋11.1111111111 %與33.3333333333 %，建立am_power.csv、載波/邊帶圖、包絡零交叉檢查，並完成以下驗收：效率增加不能支持m超過1；保留帶寬、包絡餘裕與接收方式的獨立限制。","differenceEn":"Derive and explain 11.1111111111 % and 33.3333333333 %; create am_power.csv, carrier/sideband diagram and envelope zero-crossing checks; apply this acceptance decision: Higher efficiency does not justify m>1; retain independent bandwidth, envelope-margin and receiver-type constraints.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["從原理 Carson近似B=2(deltaf+fm)估計FM主要能量頻寬；它不是精確頻譜遮罩或合規判定。 展開基準式 2*(60000+12000)；逐步記錄中間量與單位，先手算再用計算器或Python重算。接著用不同表示法交叉檢查：分別求調變指數5與2.5，再以2fm(beta+1)重算；不得把峰值偏移當峰對峰值。 將兩條推導一起存入 fm_budget.csv、調變指數表、頻譜遮罩待驗項。","從原理 單音傳統AM的兩邊帶合計功率為Pc*m²/2；總功率Pc*(1+m²/2)，效率m²/(2+m²)。 展開基準式 0.5**2/(2+0.5**2)*100；逐步記錄中間量與單位，先手算再用計算器或Python重算。接著用不同表示法交叉檢查：逐項列載波與兩邊帶功率1.25 W、5 W，再除總功率11.25 W、15 W；功率守恆。 將兩條推導一起存入 am_power.csv、載波/邊帶圖、包絡零交叉檢查。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Starting from Carson approximation B=2(deltaf+fm) estimates dominant FM bandwidth; it is not an exact spectral mask or compliance test., expand baseline expression 2*(60000+12000); record intermediate values and units, calculate manually, then repeat with a calculator or Python. Use this independent representation: Compute modulation indices5 and2.5, then cross-check with2fm(beta+1); peak deviation is not peak-to-peak deviation. Save both derivations with fm_budget.csv, modulation-index table and pending spectral-mask checks.","Starting from Single-tone conventional AM has total sideband power Pc*m²/2 and total power Pc*(1+m²/2), giving efficiency m²/(2+m²)., expand baseline expression 0.5**2/(2+0.5**2)*100; record intermediate values and units, calculate manually, then repeat with a calculator or Python. Use this independent representation: List sideband totals1.25 W and5 W, then divide by total powers11.25 W and15 W; verify power conservation. Save both derivations with am_power.csv, carrier/sideband diagram and envelope zero-crossing checks.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"comm-v28-086","referenceUrls":["https://www.etsi.org/deliver/etsi_ts/136200_136299/136211/17.04.00_60/ts_136211v170400p.pdf"],"title":"LTE MIMO：層數變化下的淨資料預算","titleEn":"LTE MIMO: useful-data budget across layer changes","why":"用兩課的可觀察驗收條件比較模型邊界：交付物能重現 144000 Hz 與 84000 Hz，保留失敗情境且每個通過判定有明確門檻；需分開列出模型未涵蓋的實際系統驗證。","whyEn":"Compare model boundaries using observable acceptance criteria: The artifacts must reproduce 144000 Hz and 84000 Hz, preserve failing scenarios and attach a threshold to each pass decision; list actual-system validation outside this model separately.","difference":"能推導並解釋1800 bit/interval與1000 bit/interval，建立lte_layers.csv、CSI年齡表、層別交付帳本，並完成以下驗收：1500位元目標需第二層有效率至少0.5；若CSI過期須重驗，不可只強制rank2。","differenceEn":"Derive and explain 1800 bit/interval and 1000 bit/interval; create lte_layers.csv, CSI-age table and per-layer delivery ledger; apply this acceptance decision: A1500-bit target needs second-layer availability at least0.5; stale CSI requires revalidation rather than forcing rank2.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["從原理 Carson近似B=2(deltaf+fm)估計FM主要能量頻寬；它不是精確頻譜遮罩或合規判定。 展開基準式 2*(60000+12000)；逐步記錄中間量與單位，先手算再用計算器或Python重算。接著用不同表示法交叉檢查：分別求調變指數5與2.5，再以2fm(beta+1)重算；不得把峰值偏移當峰對峰值。 將兩條推導一起存入 fm_budget.csv、調變指數表、頻譜遮罩待驗項。","從原理 固定每層效率時，名義位元數與可解碼層數成比例；Rank Indicator是通道適配資訊，不是保證吞吐。 展開基準式 1000+1000*0.8；逐步記錄中間量與單位，先手算再用計算器或Python重算。接著用不同表示法交叉檢查：逐層列新位元及失敗位元，不用總天線數替代成功層數；驗相同總功率假設。 將兩條推導一起存入 lte_layers.csv、CSI年齡表、層別交付帳本。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Starting from Carson approximation B=2(deltaf+fm) estimates dominant FM bandwidth; it is not an exact spectral mask or compliance test., expand baseline expression 2*(60000+12000); record intermediate values and units, calculate manually, then repeat with a calculator or Python. Use this independent representation: Compute modulation indices5 and2.5, then cross-check with2fm(beta+1); peak deviation is not peak-to-peak deviation. Save both derivations with fm_budget.csv, modulation-index table and pending spectral-mask checks.","Starting from At fixed per-layer efficiency nominal bits scale with decodable layers; rank indication is adaptation information, not a throughput guarantee., expand baseline expression 1000+1000*0.8; record intermediate values and units, calculate manually, then repeat with a calculator or Python. Use this independent representation: Tabulate new and failed bits per layer; antenna count is not successful layer count and total-power assumptions must agree. Save both derivations with lte_layers.csv, CSI-age table and per-layer delivery ledger.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v28-case-12394b4a22706b67","url":"https://ocw.mit.edu/courses/6-450-principles-of-digital-communications-i-fall-2006/","title":"Principles of Digital Communications I","titleEn":"Principles of Digital Communications I","publisher":"MIT OpenCourseWare","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v28-case-c846fbd990f7d100","url":"https://www.etsi.org/deliver/etsi_ts/136200_136299/136211/17.04.00_60/ts_136211v170400p.pdf","title":"ETSI TS 136 211 V17.4.0: E-UTRA physical channels and modulation","titleEn":"ETSI TS 136 211 V17.4.0: E-UTRA physical channels and modulation","publisher":"ETSI / 3GPP","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
